PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?follow_up_kind (COUNT(DISTINCT ?g) AS ?patients) (COUNT(DISTINCT ?follow_up) AS ?follow_ups)
WHERE {
  GRAPH ?g {
    ?follow_up a sphn:FollowUp ;
               sphn:hasCode ?follow_up_code .
    ?follow_up_code a ?follow_up_concept .
  }
  VALUES (?follow_up_concept ?follow_up_kind) {
