       (COUNT(DISTINCT ?confirmed_allergy) AS ?confirmed)
       (COUNT(DISTINCT ?suspected_allergy) AS ?suspected)
       (COUNT(DISTINCT ?refuted_allergy) AS ?refuted)
       (COUNT(DISTINCT ?error_allergy) AS ?entered_in_error)
       (ROUND(1000.0 * COUNT(DISTINCT ?confirmed_allergy) / COUNT(DISTINCT ?allergy)) / 10 AS ?confirmed_pct)
WHERE {
  GRAPH ?g {
    ?allergy a sphn:Allergy ;
             sphn:hasReactionTypeCode ?reaction_code .
    ?reaction_code a ?reaction_concept .
  }
  VALUES (?reaction_concept ?reaction_type) {
    (snomed:609328004 "allergy")
    (snomed:782197009 "intolerance")
  }
  OPTIONAL {
    GRAPH ?g {
      ?allergy sphn:hasVerificationStatusCode ?confirmed_code .
      ?confirmed_code a snomed:410605003 .
    }
    BIND (?allergy AS ?confirmed_allergy)
  }
  OPTIONAL {
    GRAPH ?g {
      ?allergy sphn:hasVerificationStatusCode ?suspected_code .
      ?suspected_code a snomed:415684004 .
    }
    BIND (?allergy AS ?suspected_allergy)
  }
  OPTIONAL {
    GRAPH ?g {
      ?allergy sphn:hasVerificationStatusCode ?refuted_code .
      ?refuted_code a snomed:723511001 .
    }
    BIND (?allergy AS ?refuted_allergy)
  }
  OPTIONAL {
    GRAPH ?g {
      ?allergy sphn:hasVerificationStatusCode ?error_code .
