PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX bif: <bif:>

SELECT ?directive_group
       (COUNT(DISTINCT ?g) AS ?patients)
       (SUM(?died) AS ?patients_with_death)
       (ROUND(1000.0 * SUM(?died) / COUNT(DISTINCT ?g)) / 10 AS ?death_pct)
       (ROUND(10 * AVG(?days)) / 10 AS ?avg_stay_days)
WHERE {
  {
    SELECT DISTINCT ?g ?directive_group
    WHERE {
      {
        GRAPH ?g {
          ?dnr a sphn:ResuscitationDirective ;
               sphn:hasCode ?dnr_code .
          ?dnr_code a snomed:304253006 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        }
        BIND ("do not resuscitate" AS ?directive_group)
      }
      UNION
      {
        GRAPH ?g {
          ?resus a sphn:ResuscitationDirective ;
                 sphn:hasCode ?resus_code .
          ?resus_code a snomed:304252001 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        }
        BIND ("resuscitate" AS ?directive_group)
      }
    }
  }
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasAdmissionDateTime ?admission ;
          sphn:hasDischargeDateTime ?discharge .
  }
  BIND (bif:datediff("day", ?admission, ?discharge) AS ?days)
  BIND (IF(EXISTS { GRAPH ?g { ?death a sphn:Death . } }, 1, 0) AS ?died)
}
GROUP BY ?directive_group
ORDER BY ?directive_group

