       (SUM(?is_billed_procedure) AS ?billed_procedures)
WHERE {
  {
    GRAPH ?g { ?procedure a sphn:OncologySurgery ; sphn:hasStartDateTime ?start . }
    BIND (1 AS ?is_cancer_surgery) BIND (0 AS ?is_radiotherapy) BIND (0 AS ?is_billed_procedure)
  }
  UNION
  {
    GRAPH ?g { ?procedure a sphn:RadiotherapyProcedure ; sphn:hasStartDateTime ?start . }
