    GRAPH ?g { ?procedure a sphn:BilledProcedure ; sphn:hasStartDateTime ?start . }
    BIND (0 AS ?is_cancer_surgery) BIND (0 AS ?is_radiotherapy) BIND (1 AS ?is_billed_procedure)
  }
  BIND (YEAR(?start) AS ?year)
  FILTER (?year >= 2015 && ?year <= 2025)
