PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?sex
       (COUNT(DISTINCT ?g) AS ?patients_with_prescription)
       (ROUND(10 * AVG(?prescriptions)) / 10 AS ?avg_prescriptions_per_patient)
       (MAX(?prescriptions) AS ?max_prescriptions_per_patient)
       (SUM(IF(?prescriptions > 3, 1, 0)) AS ?patients_with_more_than_three)
       (ROUND(1000.0 * SUM(IF(?prescriptions > 3, 1, 0)) / COUNT(DISTINCT ?g)) / 10 AS ?pct_with_more_than_three)
WHERE {
  {
    SELECT ?g (COUNT(DISTINCT ?prescription) AS ?prescriptions)
    WHERE {
      GRAPH ?g { ?prescription a sphn:DrugPrescription . }
    }
    GROUP BY ?g
  }
  GRAPH ?g {
    ?sex_record a sphn:AdministrativeSex ;
                sphn:hasCode ?sex_code .
    ?sex_code a ?sex_concept .
  }
  VALUES (?sex_concept ?sex) {
    (snomed:248153007         "male")
    (snomed:248152002         "female")
    (snomed:32570681000036106 "indeterminate")
  }
}
GROUP BY ?sex
ORDER BY DESC(?patients_with_prescription)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX chop: <https://biomedit.ch/rdf/sphn-resource/chop/>
PREFIX bif: <bif:>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?procedure) AS ?procedures)
       (ROUND(10.0 * COUNT(DISTINCT ?procedure) / COUNT(DISTINCT ?g)) / 10 AS ?avg_procedures_per_patient)
       (MAX(?procedures_of_patient) AS ?max_procedures_per_patient)
       (ROUND(10 * AVG(?hours)) / 10 AS ?avg_procedure_hours)
WHERE {
  {
    SELECT ?g (COUNT(DISTINCT ?p) AS ?procedures_of_patient)
    WHERE {
      GRAPH ?g {
        ?c a chop:00.0 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        ?p sphn:hasCode ?c .
        ?p a sphn:BilledProcedure .
      }
    }
    GROUP BY ?g
    HAVING (COUNT(DISTINCT ?p) >= 2)
  }
  {
    SELECT DISTINCT ?g ?procedure ?start ?end
    WHERE {
      GRAPH ?g {
        ?code a chop:00.0 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        ?procedure sphn:hasCode ?code .
        ?procedure a sphn:BilledProcedure ;
                   sphn:hasStartDateTime ?start ;
                   sphn:hasEndDateTime ?end .
      }
    }
  }
  BIND (bif:datediff("hour", ?start, ?end) AS ?hours)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?intent
       (COUNT(DISTINCT ?billed) AS ?billed_procedures)
       (COUNT(DISTINCT ?medical) AS ?other_medical_procedures)
       (COUNT(DISTINCT ?imaging) AS ?imaging_procedures)
       (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  VALUES (?intent_concept ?intent) {
    (snomed:373808002 "curative")
    (snomed:363676003 "palliative")
    (snomed:261004008 "diagnostic")
    (snomed:129428001 "preventive")
  }
  {
    GRAPH ?g {
      ?procedure a sphn:BilledProcedure ;
                 sphn:hasIntent ?intent_record .
      ?intent_record sphn:hasCode ?intent_code .
      ?intent_code a ?intent_concept .
    }
    BIND (?procedure AS ?billed)
  }
  UNION
  {
    GRAPH ?g {
      ?procedure a sphn:MedicalProcedure ;
                 sphn:hasIntent ?intent_record .
      ?intent_record sphn:hasCode ?intent_code .
      ?intent_code a ?intent_concept .
    }
    BIND (?procedure AS ?medical)
  }
  UNION
  {
    GRAPH ?g {
      ?procedure a sphn:ImagingProcedure ;
                 sphn:hasIntent ?intent_record .
      ?intent_record sphn:hasCode ?intent_code .
      ?intent_code a ?intent_concept .
    }
    BIND (?procedure AS ?imaging)
  }
}
GROUP BY ?intent
ORDER BY ?intent

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?tobacco_status
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?infectious_patient) AS ?with_infectious_disease_billed)
       (ROUND(1000.0 * COUNT(DISTINCT ?infectious_patient) / COUNT(DISTINCT ?g)) / 10 AS ?pct)
WHERE {
  GRAPH ?g {
    ?exposure a sphn:TobaccoExposure ;
              sphn:hasTypeCode ?type_code .
    ?type_code a ?type_concept .
  }
  VALUES (?type_concept ?tobacco_status) {
    (snomed:77176002  "current smoker")
    (snomed:8517006   "former smoker")
    (snomed:702979003 "never smoked")
  }
  OPTIONAL {
    GRAPH ?g {
      ?dx_code a icd-10-gm:01 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
      ?dx sphn:hasCode ?dx_code .
      ?dx a sphn:BilledDiagnosis .
    }
    BIND (?g AS ?infectious_patient)
  }
}
GROUP BY ?tobacco_status
ORDER BY DESC(?pct)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?cohort
       (COUNT(DISTINCT ?g) AS ?patients)
       (SUM(IF(?prescriptions > 0, 1, 0)) AS ?patients_with_prescription)
       (ROUND(1000.0 * SUM(IF(?prescriptions > 0, 1, 0)) / COUNT(DISTINCT ?g)) / 10 AS ?pct_with_prescription)
       (ROUND(10 * AVG(?prescriptions)) / 10 AS ?avg_prescriptions_per_patient)
WHERE {
  {
    SELECT ?g (COUNT(DISTINCT ?prescription) AS ?prescriptions)
    WHERE {
      GRAPH ?g { ?sex_record a sphn:AdministrativeSex . }
      OPTIONAL { GRAPH ?g { ?prescription a sphn:DrugPrescription . } }
    }
    GROUP BY ?g
  }
  BIND (IF(EXISTS {
             GRAPH ?g {
               ?dx a sphn:BilledDiagnosis ;
                   sphn:hasCode ?dx_code .
               ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
             }
           }, "cholera on a bill", "no cholera on a bill") AS ?cohort)
}
GROUP BY ?cohort
ORDER BY ?cohort

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX bif: <bif:>

SELECT ?sex
       (COUNT(DISTINCT ?g) AS ?patients_with_implant)
       (COUNT(DISTINCT ?presence) AS ?implant_episodes)
       (ROUND(10 * AVG(?days)) / 10 AS ?avg_days_in_place)
       (MAX(?days) AS ?max_days_in_place)
WHERE {
  {
    SELECT DISTINCT ?g ?presence ?start ?end
    WHERE {
      GRAPH ?g {
        ?presence a sphn:ImplantPresence ;
                  sphn:hasStartDateTime ?start ;
                  sphn:hasEndDateTime ?end .
      }
    }
  }
  GRAPH ?g {
    ?sex_record a sphn:AdministrativeSex ;
                sphn:hasCode ?sex_code .
    ?sex_code a ?sex_concept .
  }
  VALUES (?sex_concept ?sex) {
    (snomed:248153007         "male")
    (snomed:248152002         "female")
    (snomed:32570681000036106 "indeterminate")
  }
  BIND (bif:datediff("day", ?start, ?end) AS ?days)
}
GROUP BY ?sex
ORDER BY DESC(?patients_with_implant)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX bif: <bif:>

SELECT ?reason_to_stop
       (COUNT(DISTINCT ?administration) AS ?administrations)
       (COUNT(DISTINCT ?g) AS ?patients)
       (ROUND(10 * AVG(?hours)) / 10 AS ?avg_hours)
       (MIN(?hours) AS ?min_hours)
       (MAX(?hours) AS ?max_hours)
WHERE {
  {
    SELECT DISTINCT ?g ?administration ?reason_to_stop ?start ?end
    WHERE {
      GRAPH ?g {
        ?administration a sphn:DrugAdministrationEvent ;
                        sphn:hasReasonToStopCode ?reason_code ;
                        sphn:hasStartDateTime ?start ;
                        sphn:hasEndDateTime ?end .
        ?reason_code a ?reason_concept .
      }
      VALUES (?reason_concept ?reason_to_stop) {
        (snomed:395009001 "side effect")
        (snomed:182846007 "medical aim achieved")
      }
      FILTER (?end >= ?start)
    }
  }
  BIND (bif:datediff("hour", ?start, ?end) AS ?hours)
}
GROUP BY ?reason_to_stop
ORDER BY ?reason_to_stop

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients_with_lab_tests)
       (ROUND(10 * AVG(?tests)) / 10 AS ?avg_tests_per_patient)
       (MAX(?tests) AS ?max_tests_per_patient)
       (SUM(IF(?tests >= 10, 1, 0)) AS ?patients_with_10_or_more)
       (ROUND(1000.0 * SUM(IF(?tests >= 10, 1, 0)) / COUNT(DISTINCT ?g)) / 10 AS ?pct_with_10_or_more)
WHERE {
  {
    SELECT ?g (COUNT(DISTINCT ?event) AS ?tests)
    WHERE {
      GRAPH ?g { ?event a sphn:LabTestEvent . }
    }
    GROUP BY ?g
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?presence) AS ?device_placements)
       (ROUND(10 * AVG(?days)) / 10 AS ?avg_days_in_place)
       (MAX(?days) AS ?max_days_in_place)
       (SUM(IF(?days >= 7, 1, 0)) AS ?placements_a_week_or_longer)
       (ROUND(1000.0 * SUM(IF(?days >= 7, 1, 0)) / COUNT(DISTINCT ?presence)) / 10 AS ?pct_a_week_or_longer)
WHERE {
  {
    SELECT DISTINCT ?g ?presence ?start ?end
    WHERE {
      GRAPH ?g {
        ?presence a sphn:AccessDevicePresence ;
                  sphn:hasStartDateTime ?start ;
                  sphn:hasEndDateTime ?end .
      }
    }
  }
  BIND (bif:datediff("day", ?start, ?end) AS ?days)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?follow_up_result
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?follow_up) AS ?follow_ups)
       (COUNT(DISTINCT ?ae_patient) AS ?with_adverse_event)
       (ROUND(1000.0 * COUNT(DISTINCT ?ae_patient) / COUNT(DISTINCT ?g)) / 10 AS ?adverse_event_pct)
       (COUNT(DISTINCT ?cholera_patient) AS ?with_cholera_billed)
       (ROUND(1000.0 * COUNT(DISTINCT ?cholera_patient) / COUNT(DISTINCT ?g)) / 10 AS ?cholera_pct)
WHERE {
  GRAPH ?g {
    ?follow_up a sphn:FollowUp ;
               sphn:hasResult ?status .
    ?status sphn:hasCode ?status_code .
    ?status_code a ?status_concept .
  }
  VALUES (?status_concept ?follow_up_result) {
    (snomed:438949009 "alive")
    (snomed:399307001 "lost to follow-up")
  }
  OPTIONAL {
    GRAPH ?g { ?event a sphn:AdverseEvent . }
    BIND (?g AS ?ae_patient)
  }
  OPTIONAL {
    GRAPH ?g {
      ?dx a sphn:BilledDiagnosis ;
          sphn:hasCode ?dx_code .
      ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
    BIND (?g AS ?cholera_patient)
  }
}
GROUP BY ?follow_up_result
ORDER BY ?follow_up_result

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX bif: <bif:>

SELECT ?year
       (COUNT(DISTINCT ?imaging) AS ?imaging_procedures)
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?guidance_imaging) AS ?with_guidance_intent)
       (ROUND(1000.0 * COUNT(DISTINCT ?guidance_imaging) / COUNT(DISTINCT ?imaging)) / 10 AS ?guidance_pct)
       (ROUND(10 * AVG(?hours)) / 10 AS ?avg_hours)
WHERE {
  {
    SELECT DISTINCT ?g ?imaging ?start ?end
    WHERE {
      GRAPH ?g {
        ?imaging a sphn:ImagingProcedure ;
                 sphn:hasStartDateTime ?start ;
                 sphn:hasEndDateTime ?end .
      }
    }
  }
  BIND (YEAR(?start) AS ?year)
  FILTER (?year >= 2010 && ?year <= 2018)
  BIND (bif:datediff("hour", ?start, ?end) AS ?hours)
  OPTIONAL {
    GRAPH ?g {
      ?imaging sphn:hasIntent ?intent_record .
      ?intent_record sphn:hasCode ?intent_code .
      ?intent_code a snomed:429892002 .
    }
    BIND (?imaging AS ?guidance_imaging)
  }
}
GROUP BY ?year
ORDER BY ?year

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?indication
       (COUNT(DISTINCT ?prescription) AS ?prescriptions)
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?continuous_prescription) AS ?continuous)
       (ROUND(1000.0 * COUNT(DISTINCT ?continuous_prescription) / COUNT(DISTINCT ?prescription)) / 10 AS ?continuous_pct)
       (COUNT(DISTINCT ?intermittent_prescription) AS ?intermittent)
       (ROUND(1000.0 * COUNT(DISTINCT ?intermittent_prescription) / COUNT(DISTINCT ?prescription)) / 10 AS ?intermittent_pct)
       (COUNT(DISTINCT ?not_applicable_prescription) AS ?not_applicable)
       (ROUND(1000.0 * COUNT(DISTINCT ?not_applicable_prescription) / COUNT(DISTINCT ?prescription)) / 10 AS ?not_applicable_pct)
WHERE {
  GRAPH ?g {
    ?prescription a sphn:DrugPrescription ;
                  sphn:hasTimePattern ?pattern .
    ?pattern sphn:hasTypeCode ?pattern_code .
    ?pattern_code a ?pattern_concept .
  }
  VALUES ?pattern_concept { snomed:255238004 snomed:7087005 snomed:385432009 }
  BIND (IF(?pattern_concept = snomed:255238004, ?prescription, ?none) AS ?continuous_prescription)
  BIND (IF(?pattern_concept = snomed:7087005, ?prescription, ?none) AS ?intermittent_prescription)
  BIND (IF(?pattern_concept = snomed:385432009, ?prescription, ?none) AS ?not_applicable_prescription)
  BIND (IF(EXISTS {
             GRAPH ?g {
               ?prescription sphn:hasIndicationToStart ?dx .
               ?dx sphn:hasCode ?dx_code .
               ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
             }
           }, "started for cholera", "started for another reason") AS ?indication)
}
GROUP BY ?indication
ORDER BY ?indication

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?ingredient_concept
       (SAMPLE(?label) AS ?ingredient)
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?prescription) AS ?prescriptions)
       (COUNT(DISTINCT ?cholera_prescription) AS ?prescriptions_for_cholera)
       (ROUND(1000.0 * COUNT(DISTINCT ?cholera_prescription) / COUNT(DISTINCT ?prescription)) / 10 AS ?cholera_pct)
WHERE {
  GRAPH ?g {
    ?prescription a sphn:DrugPrescription ;
                  sphn:hasDrug ?drug .
    ?drug sphn:hasActiveIngredient ?substance .
    ?substance sphn:hasCode ?ingredient_code .
    ?ingredient_code a ?ingredient_concept .
  }
  FILTER (STRSTARTS(STR(?ingredient_concept), "http://snomed.info/id/"))
  OPTIONAL {
    GRAPH <https://biomedit.ch/rdf/sphn-resource/global> { ?ingredient_concept rdfs:label ?label . }
    FILTER (LANGMATCHES(LANG(?label), "en"))
  }
  OPTIONAL {
    GRAPH ?g {
      ?prescription sphn:hasIndicationToStart ?dx .
      ?dx sphn:hasCode ?dx_code .
      ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
    BIND (?prescription AS ?cholera_prescription)
  }
}
GROUP BY ?ingredient_concept
ORDER BY DESC(?patients) DESC(?prescriptions)
LIMIT 4
